<?php $this->layout('default'); use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V; ?>
<form class="cms-card" method="post" action="/acao/ticket-category-save"><h2>Nova categoria</h2><?= V::csrf() ?><div class="cms-form-grid"><?= V::field('Nome', 'name', '', ['required' => true]) ?><?= V::field('Ordem', 'sort_order', '0', ['type' => 'number']) ?></div><?= V::field('Ativa', 'is_active', '1', ['type' => 'checkbox']) ?><button class="cms-btn-primary">Salvar</button></form>
<div class="cms-card"><?php foreach (H::categories() as $c): ?><form class="cms-filters" method="post" action="/acao/ticket-category-save"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $c['id'] ?>"><div class="cms-field"><label>Nome<input name="name" value="<?= V::e($c['name']) ?>"></label></div><div class="cms-field"><label>Ordem<input type="number" name="sort_order" value="<?= (int) $c['sort_order'] ?>"></label></div><label class="cms-check"><input type="hidden" name="is_active" value="0"><input type="checkbox" name="is_active" value="1"<?= $c['is_active'] ? ' checked' : '' ?>> Ativa</label><small><?= (int) $c['tickets_count'] ?> chamados</small><button class="cms-btn">Salvar</button></form><?php endforeach; ?></div>
